      return;
    }

  d13x_panel_disable();
  d13x_de_disable();
  d13x_lvds_disable();
  wd_cancel(&g_fb.pan_wdog);
  kmm_free(g_fb.memory);
  memset(&g_fb, 0, sizeof(g_fb));
}

