#ifdef CONFIG_D13X_DISPLAY
  ret = fb_register(0, 0);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: failed to register framebuffer: %d\n", ret);
      d13x_record_error(&result, ret);
    }
  else
    {
      syslog(LOG_INFO, "LVDS framebuffer registered as /dev/fb0\n");
    }
#endif

  return result;
}
